 * - A 1x1 array is repeated across every position.
 * - A single row (1xN) array is broadcast down the rows.
 * - A single column (Nx1) array is broadcast across the columns.
 * - Any other array keeps its own values, positions outside its bounds use `defaultValue`.
 *
 * @param rowCount target row count
 * @param columnCount target column count
 * @param valueObject the source value object
 * @param defaultValue value used for out-of-bounds positions, defaults to a null value
 */
export function expandArrayValueObject(
    rowCount: number,
    columnCount: number,
    valueObject: BaseValueObject,
    defaultValue?: BaseValueObject
) {
    const result: BaseValueObject[][] = [];

    if (valueObject.isArray()) {
        const arrayValueObject = valueObject as ArrayValueObject;
        const valueRowCount = arrayValueObject.getRowCount();
        const valueColumnCount = arrayValueObject.getColumnCount();
        const values = arrayValueObject.getArrayValue();

        const getRealValue = (row: number, column: number) => values?.[row]?.[column];

        if (valueRowCount === 1 && valueColumnCount === 1) {
            const v = arrayValueObject.getFirstCell() as BaseValueObject;
            for (let r = 0; r < rowCount; r++) {
                const row: BaseValueObject[] = [];
                for (let c = 0; c < columnCount; c++) {
                    row.push(v);
                }
                result.push(row);
            }
        } else if (valueRowCount === 1 && valueColumnCount > 1) {
            for (let r = 0; r < rowCount; r++) {
                const row: BaseValueObject[] = [];
                for (let c = 0; c < columnCount; c++) {
                    const v = getRealValue(0, c) || (defaultValue ?? new NullValueObject(0));
                    row.push(v);
                }
                result.push(row);
            }
        } else if (valueColumnCount === 1 && valueRowCount > 1) {
            for (let r = 0; r < rowCount; r++) {
                const row: BaseValueObject[] = [];
                for (let c = 0; c < columnCount; c++) {
                    const v = getRealValue(r, 0) || (defaultValue ?? new NullValueObject(0));
                    row.push(v);
                }
                result.push(row);
            }
        } else {
            for (let r = 0; r < rowCount; r++) {
                const row: BaseValueObject[] = [];
                for (let c = 0; c < columnCount; c++) {
                    const v = getRealValue(r, c) || (defaultValue ?? new NullValueObject(0));
                    row.push(v);
                }
                result.push(row);
            }
        }
    } else {
        for (let r = 0; r < rowCount; r++) {
            const row: BaseValueObject[] = [];
            for (let c = 0; c < columnCount; c++) {
                row.push(valueObject);
            }
            result.push(row);
        }
    }

    return createNewArray(result, rowCount, columnCount);
}

export function createNewArray(result: BaseValueObject[][], rowCount: number, columnCount: number) {
    const arrayValueObjectData: IArrayValueObject = {
        calculateValueList: result,
        rowCount,
        columnCount,
        unitId: '',
        sheetId: '',
        row: -1,
        column: -1,
    };

    return new ArrayValueObject(arrayValueObjectData);
}
