export class Isblank extends BaseFunction {
    override calculate(value: BaseValueObject) {
        if (value == null) {
            return new ErrorValueObject(ErrorType.NA);
        }

        if (value.isNull()) {
            return new BooleanValueObject(true);
        }

        if (value.isArray()) {
            const arrayValue = value as ArrayValueObject;
            const rowCount = arrayValue.getRowCount();
            const columnCount = arrayValue.getColumnCount();
            const values = arrayValue.getArrayValue();

            const result: BaseValueObject[][] = [];

            for (let r = 0; r < rowCount; r++) {
                const row: BaseValueObject[] = [];
                for (let c = 0; c < columnCount; c++) {
                    const cell = values?.[r]?.[c];
                    const isBlank = cell == null || cell.isNull();
                    row.push(new BooleanValueObject(isBlank));
                }
                result.push(row);
            }

            return createNewArray(result, rowCount, columnCount);
        }

        return new BooleanValueObject(false);
    }
}
