import { ErrorType } from '../../../basics/error-type';
import { expandArrayValueObject } from '../../../engine/utils/array-object';
import type { ArrayValueObject } from '../../../engine/value-object/array-value-object';
import { type BaseValueObject, ErrorValueObject } from '../../../engine/value-object/base-value-object';
import { BooleanValueObject, NullValueObject } from '../../../engine/value-object/primitive-object';
import { BaseFunction } from '../../base-function';

export class If extends BaseFunction {
    override calculate(
        logicTest: BaseValueObject,
        valueIfTrue: BaseValueObject,
        valueIfFalse: BaseValueObject = new BooleanValueObject(false)
    ) {
        if (logicTest == null || valueIfTrue == null) {
            return new ErrorValueObject(ErrorType.NA);
        }

        if (logicTest.isError()) {
            return logicTest;
        }

        if (valueIfTrue.isError()) {
            return valueIfTrue;
        }

        // get single value object
        logicTest = this._getSingleValueObject(logicTest);

        if (!logicTest.isArray()) {
            return logicTest.getValue() ? valueIfTrue : valueIfFalse;
        }

        // get max row length
        const maxRowLength = Math.max(
            logicTest.isArray() ? (logicTest as ArrayValueObject).getRowCount() : 1,
            valueIfTrue.isArray() ? (valueIfTrue as ArrayValueObject).getRowCount() : 1,
            valueIfFalse.isArray() ? (valueIfFalse as ArrayValueObject).getRowCount() : 1
        );

        // get max column length
        const maxColumnLength = Math.max(
            logicTest.isArray() ? (logicTest as ArrayValueObject).getColumnCount() : 1,
            valueIfTrue.isArray() ? (valueIfTrue as ArrayValueObject).getColumnCount() : 1,
            valueIfFalse.isArray() ? (valueIfFalse as ArrayValueObject).getColumnCount() : 1
        );

        const logicTestArray = expandArrayValueObject(maxRowLength, maxColumnLength, logicTest);
        const valueIfTrueArray = expandArrayValueObject(
            maxRowLength,
            maxColumnLength,
            valueIfTrue,
            new ErrorValueObject(ErrorType.NA)
        );
        const valueIfFalseArray = expandArrayValueObject(
            maxRowLength,
            maxColumnLength,
            valueIfFalse,
            new ErrorValueObject(ErrorType.NA)
        );

        return logicTestArray.map((logicTestValue, rowIndex, columnIndex) => {
            if (logicTestValue.isNull()) {
                return new ErrorValueObject(ErrorType.NA);
            }

            const valueIfTrueValue = valueIfTrueArray.get(rowIndex, columnIndex) || new NullValueObject(0);
            const valueIfFalseValue = valueIfFalseArray.get(rowIndex, columnIndex) || new NullValueObject(0);

            return this._calculateSingleCell(logicTestValue, valueIfTrueValue, valueIfFalseValue);
        });
    }

    private _getSingleValueObject(valueObject: BaseValueObject) {
        if (
            valueObject.isArray() &&
            (valueObject as ArrayValueObject).getRowCount() === 1 &&
            (valueObject as ArrayValueObject).getColumnCount() === 1
        ) {
            return (valueObject as ArrayValueObject).getFirstCell();
        }
        return valueObject;
    }

    private _calculateSingleCell(
        logicTest: BaseValueObject,
        valueIfTrue: BaseValueObject,
        valueIfFalse: BaseValueObject
    ) {
        if (logicTest.isNull()) {
            return new ErrorValueObject(ErrorType.NA);
        }

        const logicTestValue = logicTest.getValue();

        // true or non-zero
        if (logicTestValue) {
            if (valueIfTrue.isNull()) {
                return new ErrorValueObject(ErrorType.NA);
            }

            return valueIfTrue;
        }

        if (valueIfFalse.isNull()) {
            return new ErrorValueObject(ErrorType.NA);
        }

        return valueIfFalse;
    }
}
