31	    for (const token of comparisonTokens) {
32	        if (str.startsWith(token)) {
33	            const content = str.substring(token.length);
34	            return [token, ValueObjectFactory.create(content) as BaseValueObject];
35	        }
36	    }
37	
38	    return [compareToken.EQUALS, ValueObjectFactory.create(str) as BaseValueObject];
39	}
