}", "newString": "/**
 * Compare two value objects using the given comparison token.
 *
 * Cross-type ordering follows the spreadsheet convention: numbers < strings < booleans.
 * Values of the same type are compared by their natural order, with strings compared
 * lexicographically.
 *
 * @param currentValue the value on the left-hand side of the comparison
 * @param searchValue the value on the right-hand side of the comparison
 * @param token the comparison operator
 */
export function valueObjectCompare(
    currentValue: BaseValueObject,
    searchValue: BaseValueObject,
    token: compareToken
): BooleanValueObject {
    return new BooleanValueObject(compareValue(currentValue, searchValue, token));
}

/**
 * The type ordering used when comparing values of different types.
 * numbers < strings < booleans
 */
function getTypeIndex(valueObject: BaseValueObject): number {
    if (valueObject.isNumber()) {
        return 0;
    }
    if (valueObject.isString()) {
        return 1;
    }
    if (valueObject.isBoolean()) {
        return 2;
    }
    return -1;
}

function compareValue(currentValue: BaseValueObject, searchValue: BaseValueObject, token: compareToken): boolean {
    const currentTypeIndex = getTypeIndex(currentValue);
    const searchTypeIndex = getTypeIndex(searchValue);

    // -1: currentValue < searchValue, 0: equal, 1: currentValue > searchValue
    let comparison: number;

    if (currentTypeIndex !== searchTypeIndex) {
        comparison = currentTypeIndex < searchTypeIndex ? -1 : 1;
    } else if (currentValue.isString()) {
        // lexicographic ordering for strings
        const a = `${currentValue.getValue()}`;
        const b = `${searchValue.getValue()}`;
        comparison = a === b ? 0 : a < b ? -1 : 1;
    } else {
        const a = Number(currentValue.getValue());
        const b = Number(searchValue.getValue());
        comparison = a === b ? 0 : a < b ? -1 : 1;
    }

    switch (token) {
        case compareToken.EQUALS:
            return comparison === 0;
        case compareToken.NOT_EQUAL:
            return comparison !== 0;
        case compareToken.GREATER_THAN:
            return comparison > 0;
        case compareToken.GREATER_THAN_OR_EQUAL:
            return comparison >= 0;
        case compareToken.LESS_THAN:
            return comparison < 0;
        case compareToken.LESS_THAN_OR_EQUAL:
            return comparison <= 0;
        default:
            return false;
    }
