 *
 * Cross-type ordering follows the spreadsheet convention: numbers < strings < booleans.
 * Values of the same type are compared by their natural order, with strings compared
 * lexicographically.
 *
 * When no `token` is provided, the comparison symbol is extracted from `searchValue`
 * (when it is a string, e.g. `">40"`) and the comparison is applied element-wise, keeping
 * backward compatibility with range/criteria style comparisons.
 *
 * @param currentValue the value on the left-hand side of the comparison
 * @param searchValue the value on the right-hand side of the comparison
 * @param token the comparison operator
 */
export function valueObjectCompare(
    currentValue: BaseValueObject,
    searchValue: BaseValueObject,
    token?: compareToken
): BooleanValueObject {
    if (token == null) {
        let operator = compareToken.EQUALS;
        let criteria = searchValue;

        // Only strings can extract comparison symbols, other types of values are 'equal to'
        if (searchValue.isString()) {
            const criteriaValueString = `${searchValue.getValue()}`;
            const [extractedToken, criteriaStringObject] = findCompareToken(criteriaValueString);
            operator = extractedToken;
            criteria = criteriaStringObject;
